import{_ as n,o as h,c,a2 as a}from"./chunks/framework.62rcL0wY.js";const m=JSON.parse('{"title":"Màn hình chính","description":"","frontmatter":{},"headers":[],"relativePath":"bat-dau/man-hinh-chinh.md","filePath":"bat-dau/man-hinh-chinh.md"}'),i={name:"bat-dau/man-hinh-chinh.md"};function o(r,t,s,d,e,g){return h(),c("div",null,[...t[0]||(t[0]=[a('<h1 id="man-hinh-chinh" tabindex="-1">Màn hình chính <a class="header-anchor" href="#man-hinh-chinh" aria-label="Permalink to &quot;Màn hình chính&quot;">​</a></h1><p>Trang này giới thiệu bố cục và chức năng của các nút điều khiển, bảng phím tắt toàn cục và khung thông tin trên cửa sổ chính của Clickermann.</p><div class="info custom-block"><p class="custom-block-title">Hình minh họa sẽ bổ sung</p><p>Hình chụp cửa sổ chính của Clickermann v4.13 (với hàng nút chức năng phía trên, các nút điều khiển bên trái và khung thông tin chế độ khóa cửa sổ) sẽ được bổ sung sau khi chụp trực tiếp trên máy Windows.</p></div><h2 id="vai-tro-cua-cua-so-chinh" tabindex="-1">Vai trò của cửa sổ chính <a class="header-anchor" href="#vai-tro-cua-cua-so-chinh" aria-label="Permalink to &quot;Vai trò của cửa sổ chính&quot;">​</a></h2><p>Cửa sổ chính là giao diện xuất hiện đầu tiên khi mở Clickermann, chủ yếu dùng để nạp nhanh và chạy các script đã viết sẵn, cũng như mở các cửa sổ phụ trợ.</p><p>Ở <strong>hàng nút phía trên cùng</strong> là các nút chức năng dùng để nạp tệp script (<code>.cms</code>) và mở các cửa sổ phụ trợ như cửa sổ cài đặt chương trình, cửa sổ nhật ký và <a href="/clickermann-guide-vi/bat-dau/quan-ly-cua-so.html">Quản lý cửa sổ</a>.</p><div class="tip custom-block"><p class="custom-block-title">Lưu ý về nhãn nút trên màn hình</p><p>Do chưa xác minh trực tiếp giao diện trên Windows (nhãn chữ hoặc biểu tượng thực tế trên từng nút có thể hiển thị bằng tiếng Nga hoặc tiếng Anh tùy bản), tài liệu mô tả các nút theo <strong>vị trí</strong> và khuyến khích bạn dùng <strong>phím tắt toàn cục</strong> (<code>Alt + A</code> để chạy/tạm dừng, <code>Alt + S</code> để dừng) vì phím tắt luôn hoạt động ổn định bất kể ngôn ngữ giao diện.</p></div><h2 id="cac-nut-dieu-khien-script" tabindex="-1">Các nút điều khiển script <a class="header-anchor" href="#cac-nut-dieu-khien-script" aria-label="Permalink to &quot;Các nút điều khiển script&quot;">​</a></h2><p>Ở <strong>cột phía bên trái</strong> cửa sổ chính (theo bố cục trong help) gồm 4 nút điều khiển chính:</p><ol><li><strong>Nút Chạy / Tạm dừng (phím tắt <code>Alt + A</code>):</strong><ul><li>Bắt đầu chạy script hiện tại (script vừa mở từ tệp, vừa bấm nút <strong>Áp dụng</strong> từ trình soạn thảo, hoặc vừa ghi lại).</li><li>Nếu script đang chạy mà bấm lại nút này (hoặc nhấn <code>Alt + A</code>) một lần nữa, chương trình sẽ chuyển sang <strong>tạm dừng</strong>; bấm thêm lần nữa sẽ tiếp tục chạy từ đúng câu lệnh vừa dừng.</li></ul></li><li><strong>Nút Ghi thao tác (phím tắt <code>Alt + R</code>):</strong><ul><li>Bắt đầu ghi lại các thao tác chuột và bàn phím của bạn. Mọi hành động thực hiện sau khi bấm nút này sẽ được tự động chuyển thành câu lệnh trong script.</li></ul></li><li><strong>Nút Dừng (phím tắt <code>Alt + S</code>):</strong><ul><li>Ngắt hẳn quá trình đang chạy hoặc đang ghi script. Khi chạy thử các script điều khiển chuột, hãy luôn nhớ phím tắt <strong><code>Alt + S</code></strong> để dừng ngay khi cần.</li></ul></li><li><strong>Nút mở Trình soạn thảo:</strong><ul><li>Mở cửa sổ <a href="/clickermann-guide-vi/bat-dau/trinh-soan-thao.html">Trình soạn thảo script</a> để gõ và chỉnh sửa mã lệnh.</li></ul></li></ol><h2 id="phim-tat-toan-cuc-mac-dinh" tabindex="-1">Phím tắt toàn cục mặc định <a class="header-anchor" href="#phim-tat-toan-cuc-mac-dinh" aria-label="Permalink to &quot;Phím tắt toàn cục mặc định&quot;">​</a></h2><p>Để tiện điều khiển ngay cả khi cửa sổ Clickermann không nằm ở phía trước (hoặc khi chuột đang bận chạy theo script), chương trình gắn sẵn tổ hợp phím tắt toàn cục cho các thao tác quan trọng nhất:</p><table tabindex="0"><thead><tr><th>Phím tắt mặc định</th><th>Tác dụng</th><th>Dùng ở đâu</th></tr></thead><tbody><tr><td><code>Alt + A</code></td><td><strong>Chạy / Tạm dừng</strong> script</td><td>Mọi lúc</td></tr><tr><td><code>Alt + S</code></td><td><strong>Dừng hẳn</strong> script (hoặc dừng ghi thao tác)</td><td>Mọi lúc</td></tr><tr><td><code>Alt + R</code></td><td><strong>Bắt đầu ghi</strong> thao tác chuột và bàn phím</td><td>Mọi lúc</td></tr><tr><td><code>Alt + W</code></td><td><strong>Bật khóa cửa sổ</strong> vào phần tử đang nằm dưới con trỏ chuột</td><td>Mọi lúc (xem <a href="/clickermann-guide-vi/khai-niem/khoa-cua-so.html">Chế độ khóa cửa sổ</a>)</td></tr><tr><td><code>Alt + Q</code></td><td><strong>Chèn nhanh tọa độ và màu</strong> tại mũi trỏ chuột vào script</td><td>Khi đang mở <a href="/clickermann-guide-vi/bat-dau/trinh-soan-thao.html">Trình soạn thảo</a></td></tr><tr><td><code>Alt + G</code></td><td><strong>Chụp nhanh ảnh mẫu <code>100×100</code></strong> vùng kính lúp thành tệp <code>.bmp</code></td><td>Khi đang mở <a href="/clickermann-guide-vi/bat-dau/trinh-soan-thao.html">Trình soạn thảo</a></td></tr></tbody></table><p>Bạn có thể xem hoặc thay đổi các tổ hợp phím tắt này trong cửa sổ cài đặt của chương trình.</p><h2 id="bang-thong-tin-va-che-do-chay" tabindex="-1">Bảng thông tin và chế độ chạy <a class="header-anchor" href="#bang-thong-tin-va-che-do-chay" aria-label="Permalink to &quot;Bảng thông tin và chế độ chạy&quot;">​</a></h2><p>Ngoài các nút bấm, cửa sổ chính còn có:</p><ul><li><strong>Khung thông tin chế độ khóa cửa sổ:</strong> Hiển thị trạng thái bật/tắt khóa cửa sổ, mã <code>HWND</code> của phần tử đang dưới trỏ chuột (hoặc phần tử đang khóa), mã tiến trình (<code>PID</code>) và tên tệp <code>.exe</code> của ứng dụng đó.</li><li>🟠 <strong>Khung thiết lập chế độ chạy script:</strong><ul><li><strong>Nên làm:</strong> Nếu không thấy khung hẹn số vòng lặp ngay trên cửa sổ chính của bản v4.13, hãy tìm nút mở cửa sổ thiết lập chế độ chạy trên thanh công cụ hoặc dùng lệnh <a href="/clickermann-guide-vi/lenh/kich-ban.html#halt"><code>HALT</code></a> / biến đếm trực tiếp trong script.</li></ul><details class="details custom-block"><summary>Vì sao chưa chắc</summary><p>Trong help, bài Màn hình chính ghi trên cửa sổ chính có khung thiết lập chế độ thực thi script. Tuy nhiên, trong <a href="/clickermann-guide-vi/phu-luc/lich-su.html">Lịch sử phiên bản</a> của help, bản v4.7.000 ghi đã bỏ các chế độ chạy khỏi cửa sổ chính, và bản v4.7.000 SE ghi các chế độ thực thi đã trở lại dưới dạng một cửa sổ riêng. Xem thêm tại <a href="/clickermann-guide-vi/phu-luc/can-kiem-tra-tren-windows.html#vi-tri-khung-thiet-lap-che-do-chay-script">Cần kiểm tra trên Windows</a>.</p></details></li></ul><hr><p><em>Nguồn: Tài liệu trợ giúp <code>help.chm</code> (bài Màn hình chính, Trình soạn thảo, Khóa cửa sổ và Lịch sử phiên bản).</em></p>',19)])])}const u=n(i,[["render",o]]);export{m as __pageData,u as default};
